"""Mobile-first additive presentation patch for §E v11.62 PREVIEW only.
Uses the exact sealed v11.61 source; does not change model geometry, assets or actions.
"""
CSS = "\n/* §E v11.62 adaptive phone UI, only when installed. Original native inspector stays mounted. */\n@media (max-width:700px),(max-height:600px) and (pointer:coarse){\n .model-atelier.atelier-mobile-upgrade{--atelier-keyboard-offset:0px;--atelier-visible-height:100dvh}\n .model-atelier.atelier-mobile-upgrade .atelier-tool-rail{\n  position:fixed!important;left:6px!important;right:6px!important;bottom:calc(5px + env(safe-area-inset-bottom,0px))!important;\n  top:auto!important;width:calc(100vw - 12px)!important;max-width:none!important;max-height:58px!important;\n  height:58px;display:flex!important;flex-flow:row nowrap!important;align-items:center;\n  justify-content:flex-start;gap:5px;overflow-x:auto;overflow-y:hidden;\n  scrollbar-width:thin;overscroll-behavior-x:contain;touch-action:pan-x;\n  z-index:2169;padding:5px;\n }\n .model-atelier.atelier-mobile-upgrade .atelier-tool-rail button{\n  flex:0 0 auto!important;min-width:69px!important;max-width:none!important;min-height:45px!important;\n  font-size:12px!important;white-space:nowrap!important;padding:6px!important;\n }\n .model-atelier.atelier-mobile-upgrade .atelier-context-workbench{\n  position:fixed!important;left:6px!important;right:6px!important;top:auto!important;\n  bottom:calc(66px + env(safe-area-inset-bottom,0px) + var(--atelier-keyboard-offset,0px))!important;\n  width:calc(100vw - 12px)!important;max-width:none!important;min-width:0!important;\n  max-height:calc(var(--atelier-visible-height,100dvh) - 124px)!important;\n  height:min(49dvh,calc(var(--atelier-visible-height,100dvh) - 124px))!important;\n  min-height:52px!important;\n  z-index:2168;transform:none!important;border-radius:13px;\n }\n .model-atelier.atelier-mobile-upgrade .atelier-context-workbench[data-mobile-size=\"expanded\"]{\n  height:min(76dvh,calc(var(--atelier-visible-height,100dvh) - 124px))!important;\n }\n .model-atelier.atelier-mobile-upgrade .atelier-context-workbench[data-mobile-size=\"compact\"]{\n  height:52px!important;max-height:52px!important;\n }\n .model-atelier.atelier-mobile-upgrade .atelier-context-workbench[data-mobile-size=\"compact\"] .atelier-context-title,\n .model-atelier.atelier-mobile-upgrade .atelier-context-workbench[data-mobile-size=\"compact\"] .atelier-context-body{display:none!important}\n .model-atelier.atelier-mobile-upgrade .atelier-context-header{\n  cursor:ns-resize;flex:0 0 auto;min-height:50px!important;\n  padding:3px 6px;gap:4px;touch-action:pan-y;\n }\n .model-atelier.atelier-mobile-upgrade .atelier-context-header strong{font-size:11px;white-space:nowrap}\n .model-atelier.atelier-mobile-upgrade .atelier-context-header>div{gap:3px;min-width:0}\n .model-atelier.atelier-mobile-upgrade #atelierContextNative{font-size:11px;min-height:44px!important;padding:5px 6px}\n .model-atelier.atelier-mobile-upgrade #atelierContextClose,\n .model-atelier.atelier-mobile-upgrade #atelierMobileSheetSize{min-height:44px!important;min-width:44px!important;font-size:12px;padding:5px}\n .model-atelier.atelier-mobile-upgrade #atelierMobileSheetSize{white-space:nowrap}\n .model-atelier.atelier-mobile-upgrade .atelier-context-title{\n  flex:0 0 auto;display:flex;flex-direction:row;align-items:center;justify-content:space-between;gap:6px;\n  padding:5px 8px;min-height:43px;flex-wrap:wrap;\n }\n .model-atelier.atelier-mobile-upgrade .atelier-context-title>span{display:none}\n .model-atelier.atelier-mobile-upgrade #atelierMobileHand{min-height:44px!important;padding:5px 10px;font-size:12px}\n .model-atelier.atelier-mobile-upgrade .atelier-context-body{display:flex;flex-direction:column;min-height:0;overflow:hidden;flex:1}\n .model-atelier.atelier-mobile-upgrade .atelier-context-left{flex:0 0 auto;min-height:0;max-height:156px;overflow-y:auto;padding:7px;border-right:0;border-bottom:1px solid #59758e}\n .model-atelier.atelier-mobile-upgrade .atelier-context-left label{display:none}\n .model-atelier.atelier-mobile-upgrade #atelierContextFind{\n  min-height:44px!important;font-size:14px!important;margin-bottom:5px;padding:5px 8px;\n }\n .model-atelier.atelier-mobile-upgrade #atelierContextOperations{\n  display:flex!important;flex-flow:row nowrap!important;overflow-x:auto;overflow-y:hidden;\n  gap:6px;padding:3px 0 5px;overscroll-behavior-x:contain;touch-action:pan-x;\n }\n .model-atelier.atelier-mobile-upgrade .atelier-mobile-op{display:flex;flex:0 0 auto;gap:3px;align-items:stretch;max-width:210px}\n .model-atelier.atelier-mobile-upgrade .atelier-context-op{\n  width:auto;min-width:92px;max-width:156px;min-height:44px!important;\n  padding:6px 8px;font-size:12px;white-space:normal;\n }\n .model-atelier.atelier-mobile-upgrade .atelier-mobile-op-star{min-width:44px!important;min-height:44px!important;padding:5px;font-size:19px!important}\n .model-atelier.atelier-mobile-upgrade .atelier-context-right{flex:1;min-height:0;overflow-y:auto;padding:8px 10px 14px}\n .model-atelier.atelier-mobile-upgrade #atelierContextFields{grid-template-columns:minmax(0,1fr);gap:10px}\n .model-atelier.atelier-mobile-upgrade .atelier-context-field :is(input,select,textarea,button){\n  min-height:44px!important;font-size:14px!important;padding:7px!important;\n }\n .model-atelier.atelier-mobile-upgrade .atelier-context-preset button{min-height:44px!important;font-size:12px!important}\n .model-atelier.atelier-mobile-upgrade .atelier-mobile-browse{display:flex;gap:4px;margin-bottom:4px;align-items:center}\n .model-atelier.atelier-mobile-upgrade .atelier-mobile-browse button{min-height:44px!important;font-size:12px!important;padding:4px 10px;flex:1}\n .model-atelier.atelier-mobile-upgrade .atelier-mobile-browse button[aria-pressed=true]{background:#166e76;border-color:#84eee4}\n .model-atelier.atelier-mobile-upgrade.atelier-mobile-context-mode .atelier-inspector{display:none!important}\n .model-atelier.atelier-mobile-upgrade:not(.atelier-mobile-context-mode):not(.atelier-tools-closed) .atelier-inspector{\n  position:fixed!important;left:6px!important;right:6px!important;top:auto!important;\n  bottom:calc(66px + env(safe-area-inset-bottom,0px) + var(--atelier-keyboard-offset,0px))!important;\n  width:calc(100vw - 12px)!important;height:min(43dvh,calc(var(--atelier-visible-height,100dvh) - 124px))!important;\n  min-height:130px!important;max-height:calc(var(--atelier-visible-height,100dvh) - 124px)!important;\n  z-index:2167;pointer-events:auto;border-radius:13px;overflow-y:auto;\n }\n .model-atelier.atelier-mobile-upgrade .atelier-viewport-controls{\n  top:6px!important;bottom:auto!important;left:6px!important;z-index:2161;\n }\n .model-atelier.atelier-mobile-upgrade .atelier-viewport-controls button{min-height:44px!important;min-width:44px!important}\n .model-atelier.atelier-mobile-upgrade .atelier-head button{min-height:42px}\n .model-atelier.atelier-mobile-upgrade .atelier-tool-handle button{min-height:44px!important}\n}\n@media (max-width:390px) and (orientation:portrait){\n .model-atelier.atelier-mobile-upgrade .atelier-context-header strong{display:none}\n .model-atelier.atelier-mobile-upgrade .atelier-context-left{max-height:151px}\n}\n@media (max-height:600px) and (pointer:coarse) and (orientation:landscape){\n .model-atelier.atelier-mobile-upgrade .atelier-context-workbench[data-mobile-size=\"half\"]{\n  height:min(58dvh,calc(var(--atelier-visible-height,100dvh) - 111px))!important\n }\n .model-atelier.atelier-mobile-upgrade .atelier-context-body{display:grid;grid-template-columns:minmax(160px,39%) minmax(0,1fr)}\n .model-atelier.atelier-mobile-upgrade .atelier-context-left{max-height:none;overflow-y:auto;border-right:1px solid #59758e;border-bottom:0}\n .model-atelier.atelier-mobile-upgrade #atelierContextOperations{display:flex!important;flex-direction:column!important;overflow-y:auto;overflow-x:hidden}\n .model-atelier.atelier-mobile-upgrade .atelier-mobile-op{max-width:none}\n}\n\n.model-atelier .atelier-mobile-browse{display:flex;gap:4px;margin:2px 0 5px}\n.model-atelier .atelier-mobile-browse button{min-height:34px;font-size:11px;padding:4px 6px;flex:1}\n.model-atelier .atelier-mobile-browse button[aria-pressed=true]{background:#166e76;border-color:#84eee4}\n.model-atelier .atelier-mobile-op{display:flex;align-items:stretch;gap:4px}\n.model-atelier .atelier-mobile-op .atelier-context-op{min-width:0;flex:1}\n.model-atelier .atelier-mobile-op-star{min-height:36px;min-width:34px;padding:4px;font-size:18px}\n.model-atelier .atelier-mobile-op-star[aria-pressed=true]{color:#f8d783}\n"
JS = "\n// v11.62 mobile-only presentation supervisor; native controls remain the sole source of truth.\nfunction atelierMobileLayoutInstall(panel){\n if(panel.dataset.mobileAdaptiveInstalled==='1')return;\n const sheet=panel.querySelector('#atelierContextWorkbench');\n const rail=panel.querySelector('#modelAtelierToolRail');\n const header=sheet?.querySelector('.atelier-context-header');\n if(!sheet||!rail||!header)return;\n panel.dataset.mobileAdaptiveInstalled='1';\n panel.classList.add('atelier-mobile-upgrade');\n const mql=matchMedia('(max-width:700px), (max-height:600px) and (pointer:coarse)');\n const prefKey='swyrlz-atelier-mobile-layout-v1';\n function readPrefs(){try{const data=JSON.parse(localStorage.getItem(prefKey)||'{}');return data&&typeof data==='object'?data:{}}catch(_){return {}}}\n function savePrefs(p){try{localStorage.setItem(prefKey,JSON.stringify(p))}catch(_){}}\n const preferences=readPrefs();\n let size=['compact','half','expanded'].includes(preferences.size)?preferences.size:'half';\n let handed=preferences.handed==='left'?'left':'right';\n const labels={compact:'▁ Compact',half:'▤ Half',expanded:'▣ Expand'};\n const sizes=['compact','half','expanded'];\n const resizeButton=document.createElement('button');\n resizeButton.type='button';resizeButton.id='atelierMobileSheetSize';\n resizeButton.setAttribute('aria-label','Change mobile tool sheet size');\n resizeButton.title='Cycle compact, half screen, expanded';\n header.querySelector('strong')?.after(resizeButton);\n const handButton=document.createElement('button');\n handButton.type='button';handButton.id='atelierMobileHand';\n handButton.title='Switch primary tool rail for left or right thumb';\n handButton.setAttribute('aria-label','Change tool rail handedness');\n sheet.querySelector('.atelier-context-title')?.append(handButton);\n function mobile(){return mql.matches;}\n function save(){savePrefs({size,handed});}\n function applySize(){\n  sheet.dataset.mobileSize=size;\n  resizeButton.textContent=labels[size];\n  resizeButton.setAttribute('aria-valuetext',size);\n  resizeButton.setAttribute('title','Current tool sheet size: '+size);\n  resizeButton.setAttribute('aria-expanded',String(size!=='compact'));\n }\n function applyHand(){\n  panel.dataset.atelierHanded=handed;\n  rail.dir=handed==='right'?'rtl':'ltr';\n  for(const child of rail.querySelectorAll('button'))child.dir='ltr';\n  handButton.textContent='Thumb: '+(handed==='right'?'Right':'Left');\n  handButton.setAttribute('aria-pressed',String(handed==='left'));\n }\n resizeButton.addEventListener('click',()=>{\n  size=sizes[(sizes.indexOf(size)+1)%sizes.length];\n  applySize();save();\n });\n handButton.addEventListener('click',()=>{\n  handed=handed==='right'?'left':'right';\n  applyHand();save();\n });\n // Mobile header becomes a vertical snap handle; desktop keeps native free drag.\n let drag=null;\n header.addEventListener('pointerdown',event=>{\n  if(!mobile()||event.target.closest('button,input,select,textarea'))return;\n  drag={id:event.pointerId,y:event.clientY};\n  try{header.setPointerCapture(event.pointerId)}catch(_){}\n  event.stopImmediatePropagation();event.preventDefault();\n },true);\n header.addEventListener('pointermove',event=>{\n  if(!mobile()||!drag||drag.id!==event.pointerId)return;\n  event.stopImmediatePropagation();event.preventDefault();\n },true);\n function snap(event){\n  if(!drag||drag.id!==event.pointerId)return;\n  if(mobile()){\n   const dy=event.clientY-drag.y;\n   if(Math.abs(dy)>38){\n    if(dy<0)size=size==='compact'?'half':'expanded';\n    else size=size==='expanded'?'half':'compact';\n    applySize();save();\n   }\n   event.stopImmediatePropagation();\n  }\n  drag=null;\n }\n header.addEventListener('pointerup',snap,true);\n header.addEventListener('pointercancel',snap,true);\n // Keep all tool chrome inside the visual viewport when keyboard and browser UI reduce height.\n function measure(){\n  const vv=window.visualViewport;\n  const visible=vv?.height??window.innerHeight;\n  const offset=vv?Math.max(0,window.innerHeight-visible-vv.offsetTop):0;\n  panel.style.setProperty('--atelier-visible-height',Math.round(visible)+'px');\n  panel.style.setProperty('--atelier-keyboard-offset',Math.ceil(offset)+'px');\n  if(mobile()&&sheet.hidden===false&&document.activeElement?.closest('#atelierContextFields')){\n   document.activeElement.scrollIntoView({block:'nearest',inline:'nearest'});\n  }\n }\n const original=sheet.querySelector('#atelierContextNative');\n original?.addEventListener('click',()=>{\n  if(mobile()&&panel.classList.contains('atelier-tools-closed')){\n   const more=[...rail.querySelectorAll('button')].find(b=>b.textContent.trim()==='More');\n   more?.click();\n  }\n });\n sheet.addEventListener('focusin',event=>{\n  if(!mobile()||!event.target.matches('input,select,textarea'))return;\n  requestAnimationFrame(()=>event.target.scrollIntoView({block:'nearest',inline:'nearest'}));\n });\n window.addEventListener('resize',measure,{passive:true});\n window.visualViewport?.addEventListener('resize',measure,{passive:true});\n window.visualViewport?.addEventListener('scroll',measure,{passive:true});\n mql.addEventListener?.('change',()=>{measure();applyHand()});\n applySize();applyHand();measure();\n window.SWYRL_E_MOBILE_LAYOUT=Object.freeze({\n  snapshot:()=>({mobile:mobile(),size,handed,contextOpen:!sheet.hidden,nativeVisible:!panel.classList.contains('atelier-tools-closed')&&!panel.classList.contains('atelier-mobile-context-mode')}),\n  setSize:s=>{if(sizes.includes(s)){size=s;applySize();save();}},\n  setHanded:s=>{if(s==='left'||s==='right'){handed=s;applyHand();save();}}\n });\n}\n\n// The native v11.61 context may be installed after the first Model Atelier mount.\n// Attach the mobile supervisor exactly once when the real context panel appears.\n(function atelierMobileWaitForContext(){\n const attach=()=>{\n  const panel=document.getElementById('modelAtelierPanel');\n  if(!panel||!panel.querySelector('#atelierContextWorkbench'))return false;\n  atelierMobileLayoutInstall(panel);\n  return panel.dataset.mobileAdaptiveInstalled==='1';\n };\n if(attach()||typeof MutationObserver!=='function'||!document.body)return;\n const observer=new MutationObserver(()=>{if(attach())observer.disconnect();});\n observer.observe(document.body,{childList:true,subtree:true});\n})();\n"
def apply(html):
    assert html.count('SWYRL_ENGINE_DEPLOY_MARKER: V11_61_ADAPTIVE_CONTEXT_TOOL_WORKBENCH') == 1
    assert html.count('function atelierAdaptiveInstall(panel)') == 1
    assert 'function atelierMobileLayoutInstall(panel)' not in html
    replacements = (
        ("const ModelAtelier=(()=>{", JS + "\n" + "const ModelAtelier=(()=>{"),
        ("    atelierAdaptiveInstall(panel);\n", "    atelierAdaptiveInstall(panel);\n    atelierMobileLayoutInstall(panel);\n"),
        ("panel.classList.toggle('atelier-context-active',open);", "panel.classList.toggle('atelier-context-active',open);\n  panel.classList.toggle('atelier-mobile-context-mode',open);"),
        ("if(allGroupNames.includes(label)&&open)pickGroup(label);", "if(label==='More'){\n   const leavingContext=open;\n   if(leavingContext)setOpen(false);\n   // v11.60 retains normal click-to-hide outside a contextual transition.\n   // Only recover if closing the context sheet stranded the native inspector.\n   if(leavingContext&&matchMedia('(max-width:700px), (max-height:600px) and (pointer:coarse)').matches&&panel.classList.contains('atelier-tools-closed'))b.click();\n   return;\n  }\n  if(allGroupNames.includes(label)){\n   if(matchMedia('(max-width:700px), (max-height:600px) and (pointer:coarse)').matches&&!open)setOpen(true);\n   if(open)pickGroup(label);\n  }"),
        ("</head>", '<style id="atelierMobileAdaptiveV1162">' + CSS + "</style>\n</head>"),
    )
    # The native v11.61 registry still owns operation resolution and action authority.
    old_show = " function showOps(){\n  opNav.replaceChildren();\n  const q=$('atelierContextFind').value.toLowerCase().trim();\n  const ops=operations().filter(o=>o.name.toLowerCase().includes(q)||o.ids.some(id=>titleFromId('modelAtelier'+id).toLowerCase().includes(q)));\n  if(!ops.some(o=>o.name===selectedName))selectedName=ops[0]?.name||'';\n  for(const op of ops){\n   const b=document.createElement('button');b.type='button';b.textContent=op.name;\n   b.className='atelier-context-op';b.setAttribute('aria-pressed',String(op.name===selectedName));\n   b.addEventListener('click',()=>{selectedName=op.name;showOps();});\n   opNav.append(b);\n  }\n  renderFields();\n }"
    next_show = " function showOps(){\n  opNav.replaceChildren();\n  const q=$('atelierContextFind').value.toLowerCase().trim();\n  const listed=operations().filter(o=>o.name.toLowerCase().includes(q)||o.ids.some(id=>titleFromId('modelAtelier'+id).toLowerCase().includes(q)));\n  const key=o=>group+'/'+o.name;\n  let ops=listed;\n  if(!q&&viewMode==='quick')ops=listed.filter((o,i)=>i<2||favorites.has(key(o))||recent.includes(key(o)));\n  if(!q&&viewMode==='recent')ops=listed.filter(o=>recent.includes(key(o)));\n  ops=[...ops].sort((a,b)=>{\n    const fav=Number(favorites.has(key(b)))-Number(favorites.has(key(a)));\n    if(fav)return fav;\n    if(viewMode==='recent')return recent.indexOf(key(a))-recent.indexOf(key(b));\n    return 0;\n  });\n  for(const button of browseModes.querySelectorAll('button[data-mode]')){\n    button.setAttribute('aria-pressed',String(button.dataset.mode===viewMode));\n  }\n  if(!ops.some(o=>o.name===selectedName))selectedName=ops[0]?.name||'';\n  for(const op of ops){\n    const item=document.createElement('div');item.className='atelier-mobile-op';\n    const b=document.createElement('button');b.type='button';b.textContent=op.name;\n    b.className='atelier-context-op';b.setAttribute('aria-pressed',String(op.name===selectedName));\n    b.addEventListener('click',()=>{\n      selectedName=op.name;\n      recent=[key(op),...recent.filter(v=>v!==key(op))].slice(0,15);\n      saveBrowser();showOps();\n    });\n    const star=document.createElement('button');star.type='button';star.className='atelier-mobile-op-star';\n    star.setAttribute('aria-label',(favorites.has(key(op))?'Unfavorite ':'Favorite ')+op.name);\n    star.setAttribute('aria-pressed',String(favorites.has(key(op))));\n    star.textContent=favorites.has(key(op))?'★':'☆';\n    star.addEventListener('click',()=>{\n      if(favorites.has(key(op)))favorites.delete(key(op));else favorites.add(key(op));\n      saveBrowser();showOps();\n    });\n    item.append(b,star);opNav.append(item);\n  }\n  renderFields();\n }"
    assert html.count(old_show) == 1, ('Context operation list source changed',html.count(old_show))
    html = html.replace(old_show,next_show,1)
    registry_anchor = " const opNav=$('atelierContextOperations'),fields=$('atelierContextFields'),feedback=$('atelierContextFeedback');"
    browser_ui = "\n  const browserKey='swyrlz-atelier-tool-browser-v1';\n  function browserPrefs(){try{const value=JSON.parse(localStorage.getItem(browserKey)||'{}');return value&&typeof value==='object'?value:{}}catch(_){return {}}}\n  const browserState=browserPrefs();\n  const favorites=new Set(Array.isArray(browserState.favorites)?browserState.favorites:[]);\n  let recent=Array.isArray(browserState.recent)?browserState.recent:[];\n  let viewMode=['all','quick','recent'].includes(browserState.mode)?browserState.mode:'all';\n  const saveBrowser=()=>{try{localStorage.setItem(browserKey,JSON.stringify({favorites:[...favorites],recent:recent.slice(0,15),mode:viewMode}))}catch(_){}};\n  const browseModes=document.createElement('div');browseModes.className='atelier-mobile-browse';\n  browseModes.id='atelierMobileBrowseModes';browseModes.setAttribute('role','group');browseModes.setAttribute('aria-label','Operation list display');\n  for(const name of ['All','Quick','Recent']){\n    const button=document.createElement('button');button.type='button';\n    button.textContent=name;button.dataset.mode=name.toLowerCase();browseModes.append(button);\n  }\n  opNav.before(browseModes);\n  browseModes.addEventListener('click',e=>{\n    const b=e.target.closest('button[data-mode]');if(!b)return;\n    viewMode=b.dataset.mode;saveBrowser();showOps();\n  });\n"
    assert html.count(registry_anchor) == 1
    html = html.replace(registry_anchor,registry_anchor + '\n' + browser_ui,1)
    render_head = " function renderFields(){\n"
    guarded_head = " let refreshingFields=false,scheduledFields=false;\n function renderFields(){\n  if(refreshingFields){scheduledFields=true;return;}\n  refreshingFields=true;\n  try{\n"
    render_tail = "  $('atelierContextApplyPreset').disabled=!saved;\n }\n function showOps(){"
    guarded_tail = "  $('atelierContextApplyPreset').disabled=!saved;\n  }finally{\n   refreshingFields=false;\n   if(scheduledFields){scheduledFields=false;queueMicrotask(renderFields);}\n  }\n }\n function showOps(){"
    assert html.count(render_head)==1 and html.count(render_tail)==1,'Native contextual form structure changed'
    html = html.replace(render_head,guarded_head,1).replace(render_tail,guarded_tail,1)
    for before,after in replacements:
        assert html.count(before)>=(1 if before=='</head>' else 1) and (before=='</head>' or html.count(before)==1),('Missing or ambiguous source anchor',before,html.count(before))
        html=html.replace(before,after,1)
    assert html.count('atelierMobileLayoutInstall(panel);')==2, 'Exactly one direct and one lazy attach required'
    assert html.count('SWYRL_ENGINE_DEPLOY_MARKER: V11_61_ADAPTIVE_CONTEXT_TOOL_WORKBENCH')==1
    return html
